-- 斟知知识库 · Supabase 种子数据（seed.sql）
-- 由 gen-seed.py 自动生成（解析全站 35 页 HTML），勿手工编辑；内容变更后重跑：
--   cd contract/supabase && python gen-seed.py
-- 用法：Supabase Dashboard → SQL Editor → 整段粘贴 → Run（幂等，可重复执行）。

begin;

-- 建表脚本（对应 contract/data-model.md 的 Page 实体）

create table if not exists public.pages (
  url          text primary key,            -- 站点根相对路径，如 base/ai/python/grammar.html
  title        text not null,
  section      text not null,
  content_text text not null default '',    -- 去标签正文纯文本（供 ilike 检索与摘要）
  updated_at   timestamptz not null default now()
);

-- 匿名只读（前端用 anon key 直查 PostgREST）
alter table public.pages enable row level security;
drop policy if exists "pages_public_read" on public.pages;
create policy "pages_public_read" on public.pages for select using (true);

-- 可选：全文索引列（当前前端走 ilike 即可；数据量大后可改用 rpc + websearch_to_tsquery）
alter table public.pages
  add column if not exists fts tsvector
  generated always as (to_tsvector('simple', coalesce(title, '') || ' ' || coalesce(content_text, ''))) stored;
create index if not exists pages_fts_idx on public.pages using gin (fts);


-- 灌入/更新 35 页数据
insert into public.pages (url, title, section, content_text)
values ('base/ai/deep-learning.html', '深度学习', '基础知识', '深度学习 深度学习的核心闭环： 前向算损失，反向传梯度，优化器更新参数 。本页围绕这个闭环建立最小知识体系，全部概念都可用页末的 PyTorch 示例亲手验证。 从 MLP 说起 一个神经元 = 线性变换 + 非线性激活；神经元排成层、层与层全连接，就是多层感知机（MLP）。每一层做的事： a ( l ) = σ( W ( l ) a ( l −1) + b ( l ) ) 理论上，足够宽的单隐层网络已能近似任意连续函数（万能近似定理），但 能近似 不等于 学得动 ——深层结构带来的层次化表达与参数效率才是实践中的关键。 前向与反向传播 前向传播把输入逐层变换成预测；反向传播用 链式法则 ，把损失对每个参数的梯度从后往前逐层算出。以单层计算图为例： 输入 x → z = Wx + b → a = σ(z) → 损失 L(a, y) 反向时箭头倒过来，每层只需"上游传来的梯度"乘以"本层的局部导数"： ∂ L /∂ W = ∂ L /∂ a · ∂ a /∂ z · ∂ z /∂ W 框架（如 PyTorch 的 autograd）会自动完成这一切——你只需写出前向计算，梯度自动可求。 激活函数对比 没有非线性激活，多层网络会塌缩成一层线性变换。常用激活函数速查： 激活函数 公式 优点 坑 Sigmoid 1 / (1 + e −z ) 输出 (0,1)，可解释为概率 两端饱和 → 梯度消失；输出非零中心 Tanh (e z − e −z ) / (e z + e −z ) 零中心，收敛快于 Sigmoid 仍有饱和区 ReLU max(0, z) 计算极快，正区间梯度恒为 1 死 ReLU：负区间梯度恒 0，神经元"装死" GELU z · Φ(z) 平滑非单调，Transformer 默认 计算略贵，小模型收益有限 损失函数 MSE （均方误差）：回归默认， L = (1/ n ) Σ( ŷ i − y i ) 2 ，对离群点敏感； 交叉熵 ：分类默认，度量预测概率分布与真实标签的距离，梯度干净（ p − y ），配合 sigmoid / softmax 使用。 优化器演进 优化器 一行直觉 SGD 沿当前梯度小步走，简单，但方向易震荡 Momentum 累积历史梯度当"惯性"，冲过小坑、抑制震荡 Adam 给每个参数自适应学习率，新任务的默认首选 AdamW Adam + 解耦的权重衰减，Transformer 时代标配 正则化三件套 Dropout ：训练时随机把一部分激活置零，逼网络不依赖个别神经元； 评估时必须关闭 （ model.eval() ）； 权重衰减 ：在损失中加 λ ‖ w ‖ 2 ，压制参数规模，得到更平滑的函数； BatchNorm ：把每层输入归一化到稳定分布，训练更快更稳，顺带带来轻微正则。 三者机制完全不同（去共适应 / 压参数 / 稳分布），可以组合使用，但不宜盲目堆叠。 训练循环：PyTorch 最小示例 五步口诀： zero_grad → forward → loss → backward → step 。下面用两层全连接网络拟合带噪声的一维函数，可直接运行： import torch import torch.nn as nn # 1. 数据：拟合 sin(x)，输入输出各一维 torch.manual_seed(0) x = torch.linspace(-3, 3, 200).unsqueeze(1) # 形状 (200, 1) y = torch.sin(x) + 0.1 * torch.randn_like(x) # 叠加高斯噪声 # 2. 模型：两层网络（隐藏层 64 维） device = torch.device("cuda" if torch.cuda.is_available() else "cpu") model = nn.Sequential( nn.Linear(1, 64), nn.Tanh(), # 非线性激活 nn.Linear(64, 1), ).to(device) # 模型搬到 GPU（若有） # 3. 损失与优化器 loss_fn = nn.MSELoss() optimizer = torch.optim.Adam(model.parameters(), lr=1e-2) # 4. 训练循环：口诀 zero_grad → forward → loss → backward → step for epoch in range(1000): pred = model(x.to(device)) # 前向传播 loss = loss_fn(pred, y.to(device)) # 计算损失 optimizer.zero_grad() # 清空上一步的梯度 loss.backward() # 反向传播求梯度 optimizer.step() # 用梯度更新参数 if (epoch + 1) % 200 == 0: print(f"epoch {epoch + 1:4d}, loss {loss.item():.4f}") GPU 与 device 张量与模型必须位于同一设备才能计算： .to(device) 一行即可在 CPU / GPU 间切换，其余代码不变；忘记把输入数据一起 .to(device) 是最常见报错。 过拟合诊断：看 train / val 曲线 训练时同时记录训练集与验证集损失，两条曲线的相对走势就是诊断书： 现象 诊断 药方 train 降、val 升 过拟合 Dropout / 权重衰减 / 早停 / 扩充数据 两条都高 欠拟合 加深加宽 / 换激活 / 训练更久 两条都低、val 略高 健康收敛 正常，可继续打磨数据与超参 Tip · 每次实验只动一件事 调参时一次只改学习率、网络宽度或正则强度中的一个变量，并固定随机种子，否则曲线差异无法归因。 下一步 掌握训练闭环后，进入 大模型专栏 ； 想补齐经典算法，请回顾 机器学习 。')
on conflict (url) do update set
  title = excluded.title,
  section = excluded.section,
  content_text = excluded.content_text,
  updated_at = now();

insert into public.pages (url, title, section, content_text)
values ('base/ai/machine-learning.html', '机器学习', '基础知识', '机器学习 机器学习的本质： 从数据中归纳规律，用规律预测未知 。本页给出主线脉络、核心算法直觉与一条可落地的工程工作流。 三大类范式 范式 数据形态 代表算法 监督学习 有标签 线性回归、决策树、SVM 无监督学习 无标签 K-Means、PCA 强化学习 环境反馈 Q-Learning、PPO 经典工作流 数据采集 → 数据清洗 → 特征工程 → 模型训练 → 模型评估 → 达标? → 部署上线 关键概念 过拟合与欠拟合 欠拟合 ：训练误差与测试误差都高 → 模型容量不足，增加特征或模型复杂度； 过拟合 ：训练误差低而测试误差高 → 正则化、早停、数据增强、交叉验证。 偏差—方差权衡 Error = Bias 2 + Variance + Noise 模型复杂度上升时，偏差下降、方差上升，最优点在中间。 线性回归 假设目标与特征近似线性： ŷ = w T x + b ，训练目标是最小化均方误差： min w , b Σ i ( w T x i + b − y i ) 2 两种求解视角 正规方程（闭式解） ：令梯度为零直接解出 w = ( X T X ) −1 X T y ，一步到位，但特征多时矩阵求逆又慢又不稳； 梯度下降（迭代解） ：沿负梯度方向小步更新 w ← w − η ∇ L 。批量 GD 每步用全量数据（稳但慢），SGD 每步只用一个样本（快但有噪声）——深度学习走的都是后者的变体。 from sklearn.linear_model import LinearRegression, SGDRegressor model = LinearRegression().fit(X, y) # 正规方程：闭式解 sgd = SGDRegressor(max_iter=1000).fit(X, y) # 梯度下降：迭代解 逻辑回归与交叉熵 把线性输出用 sigmoid 压到 (0,1) 当概率： p = σ( w T x + b )。分类的损失用交叉熵： L = −Σ i [ y i log p i + (1 − y i ) log(1 − p i )] Question · 为什么分类不用 MSE？ 两个原因：其一，MSE 配 sigmoid 是 非凸 函数，存在多个局部极小；其二，当预测错得离谱（ y = 1 而 p ≈ 0）时，sigmoid 处于饱和区，MSE 的梯度反而趋近 0——"错得越狠学得越慢"。交叉熵的梯度恰好是 p − y ：误差越大，更新越猛。 决策树与集成学习 Bagging / 随机森林 ：对训练集有放回采样出多份数据，各训一棵深树，最后投票平均，思路是 降方差 ——多棵"见解不同"的树互相抵消各自的过拟合；随机森林再加特征随机子集，让树之间差异更大； Boosting / XGBoost ：串行训练小树，每棵专门拟合前面所有树的 残差 （梯度），思路是 降偏差 ——一步步逼近正确答案；XGBoost 在此之上引入二阶梯度、正则项与列采样，长期霸榜表格数据。 场景 首选模型 理由 表格数据、样本中等、缺失多 随机森林 / XGBoost 对量纲、缺失、非线性天然鲁棒 关系近似线性、要解释系数 线性 / 逻辑回归 可解释、训练快、高维稀疏表现好 图像、语音、文本原始信号 深度学习 特征需要自动学习而非人工设计 特征工程 数值缩放 标准化 z = ( x − μ ) / σ 或 MinMax 压到 [0,1]。线性模型、KNN、神经网络对量纲敏感， 必须缩放 ；树模型逐特征分裂，可不做。 类别编码 One-Hot ：适合低基数无序类别（城市、性别），线性模型标配； Target 编码 ：用类别对应的目标均值替换，适合高基数（用户 ID），但统计量 只能来自训练集 ，否则直接泄漏。 缺失值策略 删行删列（缺得少且无关紧要）、中位数 / 众数填充（对离群点稳健）、追加"是否缺失"指示列（缺失本身有信息量）；树模型还可把缺失当作独立分支交给模型学。 泄漏防范 Warning · 训练集 fit，测试集只 transform 任何统计量（均值、方差、类别目标均值）都必须 只在训练集上 fit ，再应用到验证 / 测试集。"先全量归一化再划分数据"是新手最容易犯、也最难察觉的泄漏。 模型评估 分类：从混淆矩阵出发 预测为正 预测为负 实际为正 TP FN（漏报） 实际为负 FP（误报） TN 指标 定义 什么时候看它 Accuracy (TP+TN) / 总数 类别均衡时的整体正确率 Precision TP / (TP+FP) 误报代价高：垃圾邮件误杀正常邮件 Recall TP / (TP+FN) 漏报代价高：漏诊、漏掉欺诈 F1 2PR / (P+R) Precision 与 Recall 兼顾的单一数字 ROC-AUC 与阈值无关的排序能力 0.5 等于瞎猜，1.0 完美排序 Question · 不平衡数据为何不看 Accuracy？ 负样本占 99% 时，"无脑全预测负"就能拿到 99% 的 Accuracy，却一个正类也没抓到。欺诈检测、疾病筛查等场景应看 Recall、F1 或 PR 曲线。 回归指标 MAE ：平均绝对误差，对离群点鲁棒； MSE ：平方惩罚，离群点主导优化方向； R² ：相对"只预测均值"这个基线解释了多少方差，可为负。 交叉验证 K-Fold 把数据分成 K 份，轮流用 1 份做验证、其余做训练，得到 K 个分数取均值——比单次划分稳得多： from sklearn.model_selection import cross_val_score, StratifiedKFold cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=0) scores = cross_val_score(clf, X, y, cv=cv, scoring="f1_macro") print(f"{scores.mean():.3f} ± {scores.std():.3f}") 分类（尤其类别不平衡）→ StratifiedKFold ：每折保持类别比例一致； 回归 → 普通 KFold； 时间序列 → TimeSeriesSplit：绝不能用未来数据训练过去。 最小工作示例 from sklearn.datasets import load_iris from sklearn.model_selection import train_test_split from sklearn.linear_model import LogisticRegression from sklearn.metrics import accuracy_score X, y = load_iris(return_X_y=True) X_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.2, random_state=0) clf = LogisticRegression(max_iter=1000).fit(X_tr, y_tr) print(accuracy_score(y_te, clf.predict(X_te))) # ~0.97 Warning · 常见误区 评估指标要在 测试集 上看；把全量数据先归一化再划分会造成数据泄漏。 端到端 Pipeline 示例 把"填充 → 缩放 → 编码 → 模型"串成一个对象，交叉验证时每折 各自重新 fit 预处理器，从机制上杜绝泄漏： from sklearn.compose import ColumnTransformer from sklearn.pipeline import Pipeline from sklearn.impute import SimpleImputer from sklearn.preprocessing import StandardScaler, OneHotEncoder from sklearn.linear_model import LogisticRegression from sklearn.model_selection import cross_val_score, StratifiedKFold num_cols = ["age", "income"] # 数值列：中位数填充 + 标准化 cat_cols = ["city", "job"] # 类别列：众数填充 + One-Hot preprocess = ColumnTransformer([ ("num", Pipeline([ ("imp", SimpleImputer(strategy="median")), ("scale", StandardScaler()), ]), num_cols), ("cat", Pipeline([ ("imp", SimpleImputer(strategy="most_frequent")), ("onehot", OneHotEncoder(handle_unknown="ignore")), ]), cat_cols), ]) pipe = Pipeline([ ("prep", preprocess), ("clf", LogisticRegression(max_iter=1000)), ]) cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=0) scores = cross_val_score(pipe, X, y, cv=cv, scoring="roc_auc") print(f"AUC = {scores.mean():.3f} ± {scores.std():.3f}") Tip · Pipeline 是工程习惯的分水岭 预处理散落在模型之外的脚本里，迟早会在某次换数据时悄悄泄漏；用 Pipeline 绑定后，保存、加载、上线部署都是同一个对象。')
on conflict (url) do update set
  title = excluded.title,
  section = excluded.section,
  content_text = excluded.content_text,
  updated_at = now();

