values ('ds-and-algo/templates.html', '代码模板 (C++)', '数据结构与算法', '代码模板 (C++) 本页收录竞赛中最高频的代码模板，均可在 OJ 上直接使用。 快速排序 void quickSort(int a[], int l, int r) { if (l >= r) return; int i = l - 1, j = r + 1, x = a[l + r >> 1]; while (i < j) { while (a[++i] < x); while (a[--j] > x); if (i < j) swap(a[i], a[j]); } quickSort(a, l, j), quickSort(a, j + 1, r); } 二分查找 // 找左边界：满足条件的最小位置 int l = 0, r = n - 1; while (l < r) { int mid = l + r >> 1; if (check(mid)) r = mid; else l = mid + 1; } 单调栈 // 每个元素左侧第一个比它小的元素 stack<int> stk; for (int i = 0; i < n; i++) { while (!stk.empty() && a[stk.top()] >= a[i]) stk.pop(); left[i] = stk.empty() ? -1 : stk.top(); stk.push(i); } Dijkstra 最短路 vector<int> dijkstra(int s) { priority_queue<PII, vector<PII>, greater<>> pq; dist.assign(n, INF); dist[s] = 0; pq.push({0, s}); while (!pq.empty()) { auto [d, u] = pq.top(); pq.pop(); if (d > dist[u]) continue; for (auto [v, w] : g[u]) if (dist[u] + w < dist[v]) { dist[v] = dist[u] + w; pq.push({dist[v], v}); } } return dist; } 并查集 int find(int x) { return fa[x] == x ? x : fa[x] = find(fa[x]); // 路径压缩 } void unite(int a, int b) { fa[find(a)] = find(b); } 进阶模板 以下模板覆盖更复杂的场景，建议先手敲一遍，再上 OJ 用对拍数据验证。 树状数组（单点加 + 前缀和） // 适用：单点修改、区间和查询，均为 O(log n) int tr[N]; int lowbit(int x) { return x & -x; } void add(int x, int v) { // 位置 x 加上 v for (; x <= n; x += lowbit(x)) tr[x] += v; } int query(int x) { // 前缀和 [1, x] int s = 0; for (; x; x -= lowbit(x)) s += tr[x]; return s; } // 区间和 [l, r] = query(r) - query(l - 1) 线段树（区间和） // 适用：单点改 + 区间查；区间改需另加懒标记，此处省略 struct SegTree { long long sum[N << 2]; void pushup(int u) { sum[u] = sum[u << 1] + sum[u << 1 | 1]; } void build(int u, int l, int r, int *a) { if (l == r) { sum[u] = a[l]; return; } int mid = l + r >> 1; build(u << 1, l, mid, a); build(u << 1 | 1, mid + 1, r, a); pushup(u); } void update(int u, int l, int r, int p, int v) { // 点 p 加 v if (l == r) { sum[u] += v; return; } int mid = l + r >> 1; if (p <= mid) update(u << 1, l, mid, p, v); else update(u << 1 | 1, mid + 1, r, p, v); pushup(u); } long long query(int u, int l, int r, int ql, int qr) { // 区间和 if (ql <= l && r <= qr) return sum[u]; int mid = l + r >> 1; long long s = 0; if (ql <= mid) s += query(u << 1, l, mid, ql, qr); if (qr > mid) s += query(u << 1 | 1, mid + 1, r, ql, qr); return s; } }; 拓扑排序（Kahn BFS 版） // 适用：DAG 依赖排序；出队数不足 n 则存在环 vector<int> g[N]; int deg[N], q[N]; bool toposort(int n) { int hh = 0, tt = -1; for (int i = 1; i <= n; i++) if (!deg[i]) q[++tt] = i; // 入度 0 的点先入队 while (hh <= tt) { int u = q[hh++]; // 出队顺序即拓扑序 for (int v : g[u]) if (--deg[v] == 0) q[++tt] = v; } return tt == n - 1; // false 表示有环 } KMP 字符串匹配 // nxt[i]：模式串 p[1..i] 的最长相等前后缀长度；单串匹配 O(n+m) for (int i = 2, j = 0; i <= m; i++) { // 求 nxt 数组 while (j && p[i] != p[j + 1]) j = nxt[j]; if (p[i] == p[j + 1]) j++; nxt[i] = j; } for (int i = 1, j = 0; i <= n; i++) { // 在文本串 s 中匹配 p while (j && s[i] != p[j + 1]) j = nxt[j]; if (s[i] == p[j + 1]) j++; if (j == m) { /* s 中匹配终点为 i */ j = nxt[j]; } } 二分图匹配（匈牙利算法） // 适用：二分图最大匹配，复杂度 O(n·m)；match[v] 为 v 当前的配对点 int match[N]; bool vis[N]; bool dfs(int u) { for (int v : g[u]) if (!vis[v]) { vis[v] = true; // 本轮已访问，防止死循环 if (!match[v] || dfs(match[v])) { match[v] = u; return true; } } return false; } int ans = 0; // 左部每个点尝试匹配一次 for (int i = 1; i <= n; i++) { memset(vis, false, sizeof vis); ans += dfs(i); } Warning 大数据量务必开 long long 与快速 I/O（ ios::sync_with_stdio(false) ）； 递归 DFS 注意爆栈，可改显式栈。')
on conflict (url) do update set
  title = excluded.title,
  section = excluded.section,
  content_text = excluded.content_text,
  updated_at = now();

insert into public.pages (url, title, section, content_text)
values ('ds-and-algo/topic/dp.html', '动态规划', '数据结构与算法', '动态规划 动态规划 = 把原问题拆成重叠子问题，每个子问题只求解一次 。适用条件：最优子结构 + 重叠子问题。 解题框架 定义状态 ： dp[i] 表示什么（最关键的一步）； 状态转移方程 ： dp[i] 如何由更小的子问题推出； 初始化与边界 ：递推的起点； 遍历顺序 ：保证计算 dp[i] 时依赖项已就绪； 空间优化 ：滚动数组压缩维度。 经典模型 线性 DP：最长上升子序列 dp i = max j < i , a j < a i ( dp j ) + 1 for (int i = 0; i < n; i++) { dp[i] = 1; for (int j = 0; j < i; j++) if (a[j] < a[i]) dp[i] = max(dp[i], dp[j] + 1); } 贪心 + 二分可将复杂度优化到 O ( n log n )。 背包 DP 模型 转移方程 0-1 背包 dp[j] = max(dp[j], dp[j-w]+v) ， j 倒序 完全背包 同上， j 正序 分组背包 枚举每组"选哪一件" 区间 DP：石子合并 // dp[l][r] = 合并区间 [l, r] 的最小代价 for (int len = 2; len <= n; len++) for (int l = 0, r = l + len - 1; r < n; l++, r++) { dp[l][r] = INF; for (int k = l; k < r; k++) dp[l][r] = min(dp[l][r], dp[l][k] + dp[k+1][r] + sum(l, r)); } 树形 DP：没有上司的舞会 树没有环，先 把无根树转成有根树 ：任选一点作根，从根 DFS 确定父子关系，状态就能挂在“以 u 为根的子树”上。舞会问题：职员和直属上司不能同时参加，求最大快乐值之和。 // f[u][0/1]：u 不参加 / 参加时，其子树的最大快乐值 void dfs(int u) { f[u][1] = happy[u]; for (int v : g[u]) { // v 是 u 的直接下属 dfs(v); f[u][0] += max(f[v][0], f[v][1]); // 上司不来，下属随意 f[u][1] += f[v][0]; // 上司来了，下属不能来 } } // 答案：max(f[root][0], f[root][1])，root 为转有根树后的树根 状压 DP：旅行商问题 (TSP) 当 n ≤ 20 时，可以把 集合压进二进制位 ：第 i 位为 1 表示第 i 个元素在集合中。TSP 要求经过每个城市恰好一次再回到起点，状压解法复杂度 O ( n · 2 n )。 // dp[S][u]：已访问集合为 S、当前在城市 u 的最小总路程 memset(dp, 0x3f, sizeof dp); dp[1][0] = 0; // 从 0 号城市出发 for (int S = 1; S < (1 << n); S++) for (int u = 0; u < n; u++) if (S >> u & 1) for (int v = 0; v < n; v++) if (!(S >> v & 1)) dp[S | 1 << v][v] = min(dp[S | 1 << v][v], dp[S][u] + w[u][v]); // 答案：min(dp[(1 << n) - 1][u] + w[u][0])，枚举最后一个返回的城市 状压常用位运算技巧： 表达式 含义 S >> i & 1 判断第 i 个元素是否在集合中 S | 1 << i 把第 i 个元素加入集合 S & ~(1 << i) 把第 i 个元素移出集合 S & (S - 1) 消去最低位的 1，可用来判断 2 的幂 (1 << n) - 1 n 个元素的全集 常见线性模型一览 四个最常考的线性模型，把状态定义与转移放在一起对照记忆： 模型 状态定义 转移方程 LIS 最长上升子序列 dp[i] ：以 a[i] 结尾的 LIS 长度 dp[i] = max(dp[j] + 1) ，其中 j < i 且 a[j] < a[i] LCS 最长公共子序列 dp[i][j] ：A 前 i 个与 B 前 j 个字符的 LCS 长度 相等： dp[i-1][j-1] + 1 ；否则 max(dp[i-1][j], dp[i][j-1]) 编辑距离 dp[i][j] ：A 前 i 个字符变成 B 前 j 个的最少操作数 相等： dp[i-1][j-1] ；否则 min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1 最大子段和 dp[i] ：以 a[i] 结尾的最大子段和 dp[i] = max(dp[i-1] + a[i], a[i]) ，答案取全局最大值 DP 与记忆化搜索 同一个状态设计，既能 自底向上递推 ，也能 自顶向下记忆化搜索 。后者先写暴力递归、再加缓存，“要什么算什么”，往往更好想。以 LIS 为例，两种写法完全等价： // 自顶向下：记忆化搜索 int dfs(int i) { int &res = memo[i]; if (res) return res; // 已计算过，直接返回 res = 1; for (int j = 0; j < i; j++) if (a[j] < a[i]) res = max(res, dfs(j) + 1); return res; } // 自底向上：递推（答案为 max(dp[0..n-1])） for (int i = 0; i < n; i++) { dp[i] = 1; for (int j = 0; j < i; j++) if (a[j] < a[i]) dp[i] = max(dp[i], dp[j] + 1); } 如何选：转移“向前看”不直观、状态难以按序枚举时，记忆化搜索更自然；递归深度可能很大时改用递推，避免爆栈。 常见优化手段 滚动数组 ： dp[i] 只依赖 dp[i-1] 时压掉一维； 前缀和优化 ：转移是区间求和时预处理前缀； 单调队列优化 ：滑动窗口最值，见 图论 之外的专题； 矩阵快速幂 ：把线性递推（如斐波那契 f(n) = f(n-1) + f(n-2) ）写成矩阵的幂，配合快速幂把 O ( n ) 加速到 O (log n )。 Tip 能对新手讲清楚"状态为什么这样定义、转移为什么正确"，才算真正掌握该模型。 Note 刷题按模型分类：集中一段时间专攻一个模型（如背包专题），吃透再换下一个；每题追求 一题多解 ——先写暴力，再写标准 DP，最后尝试优化，比多刷十道新题收获更大。')
on conflict (url) do update set
  title = excluded.title,
  section = excluded.section,
  content_text = excluded.content_text,
  updated_at = now();

insert into public.pages (url, title, section, content_text)
values ('ds-and-algo/topic/graph.html', '图论', '数据结构与算法', '图论 图 G = ( V , E ) 由顶点与边构成，是刻画"关系与连接"的数学结构：地图导航、任务依赖、社交网络、电路布线，本质都是图上的算法问题。本页梳理最常用的图算法族——存储、遍历、最短路、拓扑排序、二分图判定与最小生成树。 存储方式 方式 空间 适用场景 邻接矩阵 O ( V 2 ) 稠密图、Floyd 邻接表 O ( V + E ) 绝大多数场景（默认选择） vector<pair<int, int>> g[N]; // g[u] 保存 (邻接点, 边权) void addEdge(int u, int v, int w) { g[u].push_back({v, w}); g[v].push_back({u, w}); // 无向图必须补反向边 } 邻接矩阵用 d[i][j] 直接存边权，无边记 INF：任意边 O (1) 可查，但对稀疏图浪费空间。 图的遍历 DFS（递归 / 栈） → 连通性、拓扑； BFS（队列） → 无权最短路。 // BFS：从 s 出发，第一次到达某点的层数即最短跳数 queue<int> q; q.push(s); vis[s] = true; dist[s] = 0; while (!q.empty()) { int u = q.front(); q.pop(); for (auto [v, w] : g[u]) // 无权图只用到邻接点 v if (!vis[v]) { vis[v] = true; // 入队时立即标记，避免重复入队 dist[v] = dist[u] + 1; // 无权图：层数即距离 q.push(v); } } // DFS：递归写法；统计连通块时对每个未访问点各发起一次 void dfs(int u) { vis[u] = true; for (auto [v, w] : g[u]) if (!vis[v]) dfs(v); } DFS 写法简洁，但递归深度达 10 5 级别会爆栈，可改显式栈（见 代码模板 ）。发起 DFS 的次数即连通块数；常见用途还有判环、割点与桥。 最短路算法对比 算法 适用 复杂度 备注 BFS 无权图 O ( V + E ) 层数即距离 Dijkstra 非负权 O ( E log V ) 堆优化版最常用 Bellman-Ford 可负权 O ( VE ) 可检测负环 Floyd 多源 O ( V 3 ) 三重循环，代码最短 Dijkstra 的堆优化实现见 代码模板 。Bellman-Ford 的队列优化版即 SPFA，平均表现好但最坏仍是 O ( VE )，可被构造数据卡掉；给每个点记入队次数，超过 n 即说明存在 负环 。Floyd 的核心语义是"只允许前 k 个点作中转"，所以 k 必须放最外层： // d 初始为邻接矩阵：d[i][i] = 0，无边为 INF for (int k = 0; k < n; k++) // k 在最外层，逐步放开中转点 for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) d[i][j] = min(d[i][j], d[i][k] + d[k][j]); 拓扑排序 用于 DAG 上的顺序问题（任务调度、依赖编译）：排出的线性序满足所有边"从前指向后"。 // Kahn 算法：不断移除入度为 0 的点 queue<int> q; for (int i = 0; i < n; i++) if (!indeg[i]) q.push(i); // 所有入度为 0 的点先入队 while (!q.empty()) { int u = q.front(); q.pop(); order.push_back(u); for (int v : g[u]) if (--indeg[v] == 0) q.push(v); // 删边，产生新的零入度点 } 若排序后 order.size() < n ，说明图中 存在环 。拓扑序还是 DAG 上 DP 的合法计算顺序，按序转移 dist[v] = max(dist[v], dist[u] + w) 即可保证处理 v 时所有前驱已算完（如 DAG 最长路）。 二分图判定 二分图指顶点可分成两组、所有边都跨组的图。判定方法： 染色 ——相邻点染不同色，图是二分图 ⇔ 不含奇数长度的环。匈牙利算法求最大匹配的前提就是二分图；工程中的用户—标签、任务—机器分配问题都可建模为二分图匹配。 // BFS 染色：color 取 0（未染）/ 1 / -1 vector<int> color(n, 0); for (int s = 0; s < n; s++) { if (color[s]) continue; // 每个连通块各染一遍 queue<int> q; q.push(s); color[s] = 1; while (!q.empty()) { int u = q.front(); q.pop(); for (auto [v, w] : g[u]) if (!color[v]) { color[v] = -color[u]; q.push(v); } // 染反色 else if (color[v] == color[u]) { /* 同色 → 非二分图 */ } } } 最小生成树 Kruskal ：边排序 + 并查集， O ( E log E )，稀疏图友好，代码短（并查集实现见 代码模板 ）； Prim ：类似 Dijkstra 的点扩张，稠密图更快（邻接矩阵版 O ( V 2 )）。 // Kruskal：边按权从小到大尝试，用并查集跳过会成环的边 sort(edges, edges + m); // 按 (w, u, v) 排序 int cnt = 0, total = 0; for (auto& [w, u, v] : edges) { if (find(u) == find(v)) continue; // 两端已连通，选它必成环 unite(u, v); total += w; if (++cnt == n - 1) break; // n 个点的生成树恰有 n-1 条边 } Tip 单源非负权 → Dijkstra；有负权 → SPFA / Bellman-Ford；多源小图 → Floyd；判环 → 拓扑或并查集。 小结 存储默认邻接表，无向图记得补反向边； BFS 求无权最短路，入队即标记；Dijkstra 遇到负权立即失效； 拓扑排序一鱼两吃：定顺序 + 判环；DAG 上的 DP 按拓扑序转移； 二分图判定用染色，二分图 ⇔ 无奇环； Kruskal 的本质是"贪心选边 + 并查集防环"，选满 n-1 条边即停。')
on conflict (url) do update set
  title = excluded.title,
  section = excluded.section,
  content_text = excluded.content_text,
  updated_at = now();

